export function moggingIconForSymbol(symbol: string) {
  return Object.hasOwn(systemAliases, symbol) ? systemAliases[symbol] : undefined
}

export function protocolIcon(symbol: string) {
  return symbol === 'sparkles' ? 'recovery' : moggingIconForSymbol(symbol) ?? 'protocol'
}
